import "../../styles/index-base.css";
import "../../styles/components/collapsible.css";
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible";
import { CaretDown } from "@phosphor-icons/react";
import type { ReactNode } from "react";
import { cn } from "../../lib/cn";

export const Collapsible = CollapsiblePrimitive.Root;

export function CollapsibleTrigger({ className, children, ...props }: CollapsiblePrimitive.Trigger.Props) {
  return (
    <CollapsiblePrimitive.Trigger className={cn("ix-collapsible__trigger", className)} {...props}>
      <span>{children}</span>
      <CaretDown aria-hidden="true" />
    </CollapsiblePrimitive.Trigger>
  );
}

export function CollapsibleContent({ className, children, ...props }: CollapsiblePrimitive.Panel.Props & { children?: ReactNode }) {
  return (
    <CollapsiblePrimitive.Panel className={cn("ix-collapsible__panel", className)} {...props}>
      <div className="ix-collapsible__content">{children}</div>
    </CollapsiblePrimitive.Panel>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-collapsible__trigger { display: flex; width: 100%; min-height: 38px; align-items: center; justify-content: space-between; gap: 16px; padding: 0 11px; border: 0; border-radius: var(--ix-radius-md); background: var(--ix-bg-subtle); color: var(--ix-fg-default); font-size: var(--ix-type-ui); font-weight: 560; text-align: left; cursor: pointer; transition: background-color var(--ix-hover-duration), color var(--ix-hover-duration); }

.ix-collapsible__trigger svg { width: 14px; height: 14px; flex: 0 0 auto; color: var(--ix-fg-subtle); transform: rotate(0); transition: transform 160ms var(--ix-ease-out); }

.ix-collapsible__trigger[data-panel-open] svg { transform: rotate(180deg); }

.ix-collapsible__trigger:focus-visible { outline: 2px solid var(--ix-focus-control); outline-offset: 2px; }

.ix-collapsible__trigger[data-disabled] { color: var(--ix-fg-disabled); cursor: not-allowed; }

.ix-collapsible__panel { overflow: hidden; }

.ix-collapsible__content { padding: 12px 11px 2px; color: var(--ix-fg-muted); font-size: var(--ix-type-ui); line-height: 1.55; }

@media (hover: hover) and (pointer: fine) {
.ix-collapsible__trigger:not([data-disabled]):hover { background: var(--ix-hover); color: var(--ix-fg-default); }
}

@media (prefers-reduced-motion: reduce) {
.ix-collapsible__trigger svg { transition-duration: 0.01ms; }
}
}
